// The Ed25519 public keys that rules files must be signed by (DEC-038): raw 32 bytes, base64.
// This is the ONLY file to change when a key is replaced (docs/RULES-SECURITY.md). A new key
// means a new zip, because the old zips carry the old one.
//
// The dev key's private half lives outside the repository, on the owner's machine.
export const DEV_RULES_KEY = "vYhz86wLLdRkTE28H4R+mbD5ybBfClMDzTOG0JnWmvk=";
// The production key is generated by the owner (US-125). Until it is pasted here, production
// builds trust no key and use the bundled rules only.
export const PROD_RULES_KEY: string | null = null;

/** The key for this build: the dev build trusts the dev site's key, the production build its own. */
export const rulesKey = (): string | null =>
  __CHANNEL__ === "dev" ? DEV_RULES_KEY : PROD_RULES_KEY;
